WITH flagged AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) > INTERVAL '30' DAY THEN 1 ELSE 0 END AS new_group_flag FROM web_events), sessionized AS (SELECT id, event_type, page, event_time, duration_sec, SUM(new_group_flag) OVER (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id_2 FROM flagged) SELECT id, event_type, event_time, duration_sec, session_id_2 FROM sessionized ORDER BY event_type NULLS FIRST
